export function describe(el) {
  if (typeof el === 'string' || typeof el === 'number') return el
  const name = typeof el.type === 'string' ? el.type : el.type.name
  const kids = el.props.children === undefined ? [] : [el.props.children].flat(Infinity)
  return [name, ...kids.filter((k) => k !== null && k !== false && k !== true && k !== undefined).map(describe)]
}

