const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

export function h(type, props, ...children) {
  return { type, props: props || {}, children: children.flat() }
}

export function renderToString(v) {
  if (v === null || v === false || v === undefined) return ''
  if (typeof v !== 'object') return esc(v)
  const attrs = Object.entries(v.props)
    .filter(([, val]) => val !== null && val !== undefined && typeof val !== 'function')
    .map(([k, val]) => ` ${k}="${esc(val)}"`)
    .join('')
  return `<${v.type}${attrs}>${v.children.map(renderToString).join('')}</${v.type}>`
}

