export function keyedDiff(oldKeys, newKeys) {
  const oldIndex = new Map(oldKeys.map((k, i) => [k, i]))
  const newSet = new Set(newKeys)
  const removed = oldKeys.filter((k) => !newSet.has(k))
  const added = [], moved = []
  let lastIndex = -1
  for (const k of newKeys) {
    if (!oldIndex.has(k)) { added.push(k); continue }
    const i = oldIndex.get(k)
    if (i < lastIndex) moved.push(k)
    else lastIndex = i
  }
  return { removed, added, moved }
}

