export function buildFibers(tree, parent = null) {
  const fiber = { name: tree.name, child: null, sibling: null, return: parent }
  let prev = null
  for (const c of tree.children ?? []) {
    const f = buildFibers(c, fiber)
    if (prev) prev.sibling = f
    else fiber.child = f
    prev = f
  }
  return fiber
}

export function walk(root) {
  const out = []
  let node = root
  while (node) {
    out.push(node.name)
    if (node.child) { node = node.child; continue }
    while (node && node !== root && !node.sibling) node = node.return
    if (!node || node === root) break
    node = node.sibling
  }
  return out
}

