export function createWorkLoop(units, { budget, now }) {
  let i = 0
  return {
    runSlice() {
      const start = now()
      let processed = 0
      while (i < units.length && now() - start < budget) {
        units[i++]()
        processed++
      }
      return { done: i >= units.length, processed }
    },
  }
}

