export function createScheduler() {
  let queue = []
  let seq = 0
  return {
    schedule(name, priority) { queue.push({ name, priority, seq: seq++ }) },
    flush() {
      const out = queue.sort((a, b) => a.priority - b.priority || a.seq - b.seq).map((t) => t.name)
      queue = []
      return out
    },
  }
}

